// Center of mass of two bodies:  x_cm = (m1*x1 + m2*x2) / (m1 + m2)
// The heavier mass pulls the balance point toward itself.
const m1 = P.m1, m2 = P.m2;
const v = H.plot2d({ xMin: -6, xMax: 6, yMin: -3, yMax: 3 });
v.grid(); v.axes();
// the two masses slide along a massless rod, oscillating in view
const x1 = -3 + 1.2 * Math.sin(t * 0.8);
const x2 =  3 + 1.2 * Math.sin(t * 0.8 + 1.7);
const y = 0;
const xcm = (m1 * x1 + m2 * x2) / Math.max(1e-6, m1 + m2);
// the connecting rod
v.line(x1, y, x2, y, { color: H.colors.axis, width: 3 });
// masses: radius scales with mass (visual cue)
const r1 = 8 + 4 * Math.sqrt(m1);
const r2 = 8 + 4 * Math.sqrt(m2);
v.circle(x1, y, r1, { fill: H.colors.accent });
v.circle(x2, y, r2, { fill: H.colors.accent2 });
v.text("m1", x1, y - 1.0, { color: H.colors.accent, size: 12, align: "center" });
v.text("m2", x2, y - 1.0, { color: H.colors.accent2, size: 12, align: "center" });
// the center of mass (balance point) and a fulcrum triangle below it
